/**
 * Backend client. The TV is a cache-and-sync client; the ledger's home is the
 * server. Every call here falls back to the offline cache, never to a spinner
 * of shame.
 */

import {
  cacheShelf,
  drainCompletions,
  queueCompletion,
  readCachedShelf,
  removeCompletion,
} from "../state/offline";
import type { ScreenDefinition } from "../state/screens";
import { familyKeyHeaders, storedFamilyId } from "./family-key";

export interface FaceKid {
  id: string;
  name: string;
  avatarImage: string | null;
}

export interface StoreItem {
  id: string;
  title: string;
  price: number;
  /** App-relative bundled asset path or absolute URL. */
  image: string;
}

export interface StoreListing {
  wallet: number;
  items: StoreItem[];
}

export interface MinoApi {
  /** The face picker's list. Null when unreachable - the caller keeps its fallback. */
  getKids(): Promise<FaceKid[] | null>;
  /** Today's shelf for a kid, server-driven definition. Never throws. */
  getShelf(kidId: string): Promise<Extract<ScreenDefinition, { kind: "shelf" }>>;
  /** Optimistic locally, queued when offline, synced when back. The server's
   * verdict (stars minted, goes progress) comes back when online; a
   * definitive refusal comes back TYPED (TRIP-A) so the caller resyncs to
   * server truth instead of celebrating a ghost. */
  markDone(
    kidId: string,
    cardId: string,
    opts?: { stepUp?: boolean; answerId?: string },
  ): Promise<{
    done: boolean;
    starsEarned: number;
    goesDone: number;
    goesRequired: number;
    /** R11: the mark queued offline - the moment plays with the pending-star
     * treatment and the later sync never refires it. */
    pendingSync?: boolean;
    /** TRIP-A: set on a definitive server refusal (card not active/unknown) -
     * done/stars are zero; the caller must resync, never celebrate. */
    refused?: { status: number; reason: string };
    /** I-0042: quiz verdicts carry the answer key post-commit so the reveal
     * renders without the shelf shipping it. */
    wasRight?: boolean | null;
    correctAnswerId?: string | null;
  }>;
  /** R21 take-back. Typed result (TRIP-1): a definitive refusal carries its
   * reason (already-spent / already undone / no open completion) so the kid
   * gets an honest decline, never silence. queued=true when offline. */
  undoDone(
    kidId: string,
    cardId: string,
  ): Promise<{ ok: boolean; queued?: boolean; refused?: { status: number; reason: string } }>;
  /** Runtime pairing (2026-09-14): validate a typed family key by asking
   * get-kids to resolve it - ok carries the household id + faces, refused
   * means the server answered 401/400. Never throws. */
  pairResolve(
    key: string,
  ): Promise<
    | { kind: "ok"; family: string; kids: FaceKid[] }
    | { kind: "refused"; status: number }
    | { kind: "offline" }
  >;
  /** Beta store (user-flows v5 decision 11): BROWSE only - the listing read.
   * Redemption is offline fulfillment recorded; no transaction surface
   * ships in the app, so there is no redeem call here. Null = unreadable
   * (offline or refused), the caller renders recovery. */
  getStore(kidId: string): Promise<StoreListing | null>;
}

// The backend's absolute home. The env override stays for dev proxies, but
// the default must be the real host: a build that forgets the env var
// otherwise falls back to a relative "/api", which on the github.io Pages
// host resolves to sriaitoolkit.github.io/api (404/405 on every call) and
// reads as the muddled screen with a healthy backend (regression shipped
// 2026-09-13 in the store-browse deploy; founder's TV, diag overlay showed
// app calls 404ing while direct probes returned 200).
const API_BASE =
  (import.meta.env?.VITE_NILA_API_BASE as string | undefined) ??
  "https://exrolfmurvaecgkukzrk.supabase.co/functions/v1";

/** F3b: a definitive server refusal (4xx/5xx) is an ANSWER, not offline -
 * only a genuine network failure queues a mark. */
type PostResult =
  | { kind: "ok"; json: unknown }
  | { kind: "refused"; status: number; body: unknown }
  | { kind: "offline" };

async function postJson(path: string, body: unknown, kidId?: string): Promise<PostResult> {
  try {
    const res = await fetch(`${API_BASE}${path}`, {
      method: "POST",
      headers: { "content-type": "application/json", ...familyKeyHeaders(kidId) },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      // TRIP-A: carry the refusal through - the body's error key is the
      // reason the UI needs to resync honestly instead of ghosting.
      const body = (await res.json().catch(() => null)) as unknown;
      return { kind: "refused", status: res.status, body };
    }
    return { kind: "ok", json: (await res.json()) as unknown };
  } catch {
    return { kind: "offline" };
  }
}

export function createApi(): MinoApi {
  return {
    async getKids() {
      try {
        // L1 closure (2026-09-13): the picker asks for ITS household by id,
        // build-time bound per install (VITE_NILA_FAMILY_ID); the server no
        // longer hardcodes the pilot family. Env unset -> no family param ->
        // 400 -> null -> the bundled demo-only fallback below.
        // Build-time id first (embedded installs); the paired-device id
        // second (runtime pairing - the APK loads the public bundle).
        const family =
          (import.meta.env?.VITE_NILA_FAMILY_ID as string | undefined) ?? storedFamilyId() ?? "";
        const res = await fetch(`${API_BASE}/get-kids?family=${encodeURIComponent(family)}`, {
          headers: familyKeyHeaders(),
        });
        if (!res.ok) throw new Error(`kids ${res.status}`);
        const json = (await res.json()) as { kids: FaceKid[] };
        return json.kids;
      } catch {
        return null;
      }
    },
    async pairResolve(key) {
      try {
        const res = await fetch(`${API_BASE}/get-kids`, {
          headers: { "x-nila-family-key": key.trim().toLowerCase() },
        });
        if (!res.ok) return { kind: "refused", status: res.status };
        const json = (await res.json()) as { family: string; kids: FaceKid[] };
        return { kind: "ok", family: json.family, kids: json.kids };
      } catch {
        return { kind: "offline" };
      }
    },
    async getShelf(kidId) {
      for (let attempt = 0; attempt < 3; attempt += 1) {
        try {
          // Old-TV WebViews (pre-Chrome 66) lack AbortController and
          // Promise.finally; an unguarded `new AbortController()` throws
          // synchronously, both attempts die, and a healthy backend reads as
          // the muddled screen (founder's TV, 2026-09-13: get-kids worked,
          // get-shelf 500'd client-side with 200s in the edge logs).
          const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
          const timeout = controller ? setTimeout(() => controller.abort(), 7000) : null;
          // old-WebView parity: no options object at all unless something
          // rides it (a pinned no-AbortController path asserts plain fetch).
          const keyHeaders = familyKeyHeaders(kidId);
          const opts = controller
            ? {
                signal: controller.signal,
                ...(keyHeaders["x-nila-family-key"] ? { headers: keyHeaders } : {}),
              }
            : keyHeaders["x-nila-family-key"]
              ? { headers: keyHeaders }
              : undefined;
          const res = await fetch(`${API_BASE}/get-shelf?kid=${encodeURIComponent(kidId)}`, opts);
          if (timeout !== null) clearTimeout(timeout);
          if (!res.ok) {
            // Tenancy: a 401 is an auth refusal, not a fault - retrying is
            // pointless and the cache must NOT pose as fresh truth over it.
            // Return the marked shell; App routes it to the pairing screen.
            if (res.status === 401)
              return {
                kind: "shelf",
                kidId,
                kidName: "",
                cards: [],
                wallet: 0,
                weekEarned: 0,
                weekLine: 42,
                streakRun: 0,
                boostActive: false,
                pairNeeded: true,
              };
            throw new Error(`shelf ${res.status}`);
          }
          const json = (await res.json()) as Extract<ScreenDefinition, { kind: "shelf" }>;
          void cacheShelf(kidId, JSON.stringify(json));
          void syncQueue();
          return json;
        } catch {
          // One bounded retry covers an intermittent cold function start.
        }
      }
      const cached = await readCachedShelf(kidId);
      if (cached)
        return {
          ...(JSON.parse(cached) as Extract<ScreenDefinition, { kind: "shelf" }>),
          // TRIP-A: the cache is a moment old - marked stale so the shelf
          // says so instead of posing as fresh server truth.
          stale: true,
        };
      return {
        kind: "shelf",
        kidId,
        kidName: "",
        cards: [],
        wallet: 0,
        weekEarned: 0,
        weekLine: 42,
        streakRun: 0,
        boostActive: false,
        loadFailed: true,
      };
    },
    async markDone(kidId, cardId, opts) {
      const res = await postJson(
        "/complete",
        {
          kidId,
          cardId,
          ...(opts?.stepUp ? { stepUp: true } : {}),
          ...(opts?.answerId ? { answerId: opts.answerId } : {}),
        },
        kidId,
      );
      if (res.kind === "offline") {
        await queueCompletion({
          queuedAt: Date.now(),
          kidId,
          cardId,
          action: "i-did-it",
          ...(opts?.answerId ? { answerId: opts.answerId } : {}),
        });
        // R11: the mark landed locally and queued - the moment plays with the
        // pending-star treatment and the later sync never refires it.
        return { done: true, starsEarned: 0, goesDone: 0, goesRequired: 0, pendingSync: true };
      }
      if (res.kind === "refused") {
        const reason =
          res.body && typeof (res.body as { error?: unknown }).error === "string"
            ? (res.body as { error: string }).error
            : `http-${res.status}`;
        return {
          done: false,
          starsEarned: 0,
          goesDone: 0,
          goesRequired: 0,
          refused: { status: res.status, reason },
        };
      }
      return res.json as {
        done: boolean;
        starsEarned: number;
        goesDone: number;
        goesRequired: number;
        pendingSync?: boolean;
      };
    },
    async undoDone(kidId, cardId) {
      const res = await postJson("/undo", { kidId, cardId }, kidId);
      if (res.kind === "offline") {
        await queueCompletion({ queuedAt: Date.now(), kidId, cardId, action: "undo" });
        return { ok: false, queued: true };
      }
      if (res.kind === "refused") {
        const reason =
          res.body && typeof (res.body as { error?: unknown }).error === "string"
            ? (res.body as { error: string }).error
            : `http-${res.status}`;
        return { ok: false, refused: { status: res.status, reason } };
      }
      return { ok: true };
    },
    async getStore(kidId) {
      try {
        const res = await fetch(`${API_BASE}/get-store?kid=${encodeURIComponent(kidId)}`, {
          headers: familyKeyHeaders(kidId),
        });
        if (!res.ok) return null;
        return (await res.json()) as StoreListing;
      } catch {
        return null;
      }
    },
  };
}

type QueueRefusedListener = (kidId: string) => void;
const queueRefusedListeners = new Set<QueueRefusedListener>();

/** TRIP-A: a queued completion the server definitively refuses still leaves
 * the queue (F3) - subscribers resync that kid to server truth so the
 * optimistic pending star never stands as a ghost. */
export function onQueueRefused(listener: QueueRefusedListener): () => void {
  queueRefusedListeners.add(listener);
  return () => {
    queueRefusedListeners.delete(listener);
  };
}

async function syncQueue(): Promise<void> {
  const queued = await drainCompletions();
  for (const entry of queued) {
    const res = await postJson(
      entry.action === "i-did-it" ? "/complete" : "/undo",
      entry,
      entry.kidId,
    );
    if (res.kind === "offline") break; // still offline; keep the rest queued
    // Answered - paid once already, or a definitive refusal: either way the
    // entry leaves the queue and is never replayed again (F3). Drained
    // entries always carry their auto-assigned id (F12).
    if (entry.id === undefined) throw new Error("queued completion missing id");
    await removeCompletion(entry.id);
    if (res.kind === "refused") queueRefusedListeners.forEach((listener) => listener(entry.kidId));
  }
}
