/* Welcome routing seen-flags (PM ruling 2026-09-14, relayed via main):
   (1) FIRST-OPEN of the app is device-level: root = welcome, once per
   install, then it retires. (2) PER-PROFILE first entry: a profile created
   in a later session gets welcome once before its world. (3) NEVER on
   repeat opens. Amendment (scope narrowed by PM decision message 2026-09-21 08:12 IST, P0-1 acceptance; production walkthrough nila-internal@08bf1cb3): only the FIRST
   profile of the first-open session skips its per-profile welcome (no
   back-to-back intro for that one kid); profiles 2+ still get their hello
   on first pick. Demo profiles are NOT exempt (confirmed).
   Household-local flags only (DPDP-consistent): nothing leaves the device;
   a fresh install or cleared data re-triggers first-open, which the ruling
   accepts. Old-WebView safe: plain localStorage, no modern APIs. */
const DEVICE_KEY = "nila:welcome:device";
const PROFILES_KEY = "nila:welcome:profiles";

const storage = (): Storage | undefined =>
  typeof localStorage !== "undefined"
    ? localStorage
    : (globalThis as { localStorage?: Storage }).localStorage;

export function deviceWelcomed(): boolean {
  try {
    return storage()?.getItem(DEVICE_KEY) === "1";
  } catch {
    return false;
  }
}

export function markDeviceWelcomed(): void {
  try {
    storage()?.setItem(DEVICE_KEY, "1");
  } catch {
    /* storage full/blocked: worst case welcome shows again next open */
  }
}

const readProfiles = (): string[] => {
  try {
    const raw = storage()?.getItem(PROFILES_KEY);
    const parsed: unknown = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed.filter((v): v is string => typeof v === "string") : [];
  } catch {
    return [];
  }
};

export function profileWelcomed(kidId: string): boolean {
  return readProfiles().includes(kidId);
}

export function markProfileWelcomed(kidId: string): void {
  if (!kidId) return;
  const list = readProfiles();
  if (list.includes(kidId)) return;
  list.push(kidId);
  try {
    storage()?.setItem(PROFILES_KEY, JSON.stringify(list));
  } catch {
    /* same failure posture as markDeviceWelcomed */
  }
}

/* First-profile skip on the non-pairing path (PM decision message 2026-09-21 08:12 IST, P0-1 acceptance; production walkthrough nila-internal@08bf1cb3): the FIRST profile of the
   first-open session skips its per-profile welcome - the device welcome just
   played, so a second back-to-back intro is the observed welcome -> picker ->
   welcome loop (production walkthrough 2026-09-21, nila-internal@08bf1cb3).
   The pairing path applies this skip at pair time (markProfileWelcomed on the
   first household profile); the demo/offline path has no pair step, so the
   pick itself asks here: skip only while no profile has been welcomed yet. */
export function shouldSkipFirstProfileWelcome(firstOpenSession: boolean): boolean {
  if (!firstOpenSession) return false;
  return readProfiles().length === 0;
}
