// DS-1 picker port (2026-09-14): every DOM focus call opts out of the UA's
// focus-into-view scroll. FocusRoot owns scrolling (clamped center-scroll in
// Focusable); a second uncontrolled scroller nudges overflowing rows at
// first paint and clips siblings. Pre-Chrome-68 WebViews (old TVs) ignore
// the options object and keep today's behavior - graceful, no crash.
export function focusPreventScroll(el: { focus: (options?: FocusOptions) => void }): void {
  el.focus({ preventScroll: true });
}
