/**
 * Timer finish chime (spec v3-r "Audio"). Web Audio unlocked only from a
 * verified user gesture (event.isTrusted); bundled short MP3 (<6s) with an
 * <audio> fallback for old WebViews. Any failure -> visual-only, silently.
 * Never loops, vibrates or flashes; stops on any key, page hide or app exit.
 */
export const CHIME_URL = `${import.meta.env?.BASE_URL ?? "/"}assets/timer/chime.mp3`;
export const CHIME_MAX_MS = 6_000;

export class TimerChime {
  private ctx: AudioContext | null = null;
  private buffer: AudioBuffer | null = null;
  private source: AudioBufferSourceNode | null = null;
  private el: HTMLAudioElement | null = null;
  private stopTimer: ReturnType<typeof setTimeout> | null = null;
  private unlocked = false;

  constructor(
    private readonly url: string = CHIME_URL,
    private readonly volume: () => number = () => 1,
    private readonly muted: () => boolean = () => false,
  ) {}

  /** Call from a trusted gesture handler (the preset press). */
  unlock(ev: { isTrusted: boolean }): void {
    if (!ev.isTrusted || this.unlocked) return;
    this.unlocked = true;
    try {
      const Ctor =
        (
          globalThis as unknown as {
            AudioContext?: typeof AudioContext;
            webkitAudioContext?: typeof AudioContext;
          }
        ).AudioContext ??
        (globalThis as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (Ctor) {
        this.ctx = new Ctor();
        void this.ctx.resume().catch(() => undefined);
        void fetch(this.url)
          .then((r) => r.arrayBuffer())
          .then((b) => this.ctx?.decodeAudioData(b))
          .then((buf) => {
            this.buffer = buf ?? null;
          })
          .catch(() => {
            this.buffer = null;
          });
      }
    } catch {
      this.ctx = null;
    }
    try {
      this.el = new Audio(this.url);
      this.el.loop = false;
      this.el.preload = "auto";
    } catch {
      this.el = null;
    }
  }

  play(): void {
    this.stop();
    if (!this.unlocked || this.muted()) return;
    const vol = Math.max(0, Math.min(1, this.volume()));
    try {
      if (this.ctx && this.buffer) {
        const src = this.ctx.createBufferSource();
        const gain = this.ctx.createGain();
        gain.gain.value = vol;
        src.buffer = this.buffer;
        src.loop = false;
        src.connect(gain).connect(this.ctx.destination);
        src.start();
        this.source = src;
      } else if (this.el) {
        this.el.volume = vol;
        this.el.currentTime = 0;
        void this.el.play().catch(() => undefined);
      }
    } catch {
      /* visual-only */
    }
    this.stopTimer = setTimeout(() => this.stop(), CHIME_MAX_MS);
  }

  stop(): void {
    if (this.stopTimer) clearTimeout(this.stopTimer);
    this.stopTimer = null;
    try {
      this.source?.stop();
    } catch {
      /* already stopped */
    }
    this.source = null;
    if (this.el) {
      try {
        this.el.pause();
      } catch {
        /* ignore */
      }
    }
  }
}
