/**
 * Timer host (spec v3-r "Utility overlay"): the low-prominence launcher on
 * every production screen + the overlay. Owns lifecycle only - storage and
 * clocks via TimerController, focus via focus-session. App.tsx mounts it
 * once inside FocusRoot and passes the current screen identity.
 */
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { Focusable, useFocusContext } from "../../focus/FocusRoot";
import {
  FALLBACK_FOCUS_ID,
  createFocusSessionMachine,
  overlayFocusableIds,
  type FocusSessionToken,
} from "../../focus/focus-session";
import {
  defaultPresentation,
  utilityLabel,
  type TimerPresentation,
} from "../../../../../packages/domain/src/timer";
import { TimerStorage } from "../../state/timer-storage";
import { TimerChime } from "./timer-audio";
import { TimerController, type TimerSnapshot } from "./timer-controller";
import { ENTRY_FOCUS, TimerOverlay, type TimerActions } from "./TimerOverlay";
import "./timer.css";

const TICK_MS = 250;

function prefersReducedMotion(): boolean {
  try {
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  } catch {
    return false;
  }
}

export function TimerHost({
  screenId,
  keyEnabled,
  kidAge = null,
}: {
  /** Screen identity for origin-focus restore (e.g. "shelf:kid-1", "leave"). */
  screenId: string;
  /** false while another modal (Leave Nila?) owns keys: remote open is inert. */
  keyEnabled: boolean;
  kidAge?: number | null;
}) {
  const ctx = useFocusContext();
  // The focus context value changes on every focus move; everything below
  // that must outlive a move (session machine, entry focus) reads it via ref.
  const ctxRef = useRef(ctx);
  ctxRef.current = ctx;
  const nav = ctx?.nav ?? null;
  const presentation: TimerPresentation = defaultPresentation(kidAge);
  const chime = useMemo(() => new TimerChime(), []);
  const controller = useMemo(
    () =>
      new TimerController(
        new TimerStorage(),
        { wall: () => Date.now(), mono: () => performance.now() },
        { finish: () => chime.play(), stop: () => chime.stop() },
        presentation,
      ),
    // One controller per install; presentation default only seeds new timers.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [chime],
  );
  const [snap, setSnap] = useState<TimerSnapshot>(controller.snapshot());
  const [reduced, setReduced] = useState(prefersReducedMotion());
  const session = useMemo(
    () =>
      createFocusSessionMachine({
        focused: () => ctxRef.current?.nav.focused ?? null,
        focus: (id) => {
          const c = ctxRef.current;
          if (!c?.nav.focus(id)) return false;
          c.focus(id);
          return true;
        },
      }),
    [],
  );
  const token = useRef<FocusSessionToken | null>(null);
  const overlayRef = useRef<HTMLDivElement>(null);
  const screenRef = useRef(screenId);
  screenRef.current = screenId;

  useEffect(() => controller.subscribe(setSnap), [controller]);
  useEffect(() => {
    void controller.load();
  }, [controller]);
  useEffect(() => {
    const id = setInterval(() => void controller.tick(), TICK_MS);
    const vis = () => (document.hidden ? controller.pageHidden() : void controller.pageVisible());
    const hide = () => controller.pageHidden();
    document.addEventListener("visibilitychange", vis);
    window.addEventListener("pagehide", hide);
    let mq: MediaQueryList | null = null;
    const onMq = () => setReduced(prefersReducedMotion());
    try {
      mq = window.matchMedia("(prefers-reduced-motion: reduce)");
      mq.addEventListener?.("change", onMq);
    } catch {
      mq = null;
    }
    return () => {
      clearInterval(id);
      document.removeEventListener("visibilitychange", vis);
      window.removeEventListener("pagehide", hide);
      mq?.removeEventListener?.("change", onMq);
      chime.stop();
    };
  }, [controller, chime]);

  // Track page content focus while closed (origin for pointer-opened sessions).
  useEffect(() => {
    if (!snap.state.open) session.noteContentFocus(ctx?.focused ?? null);
  }, [ctx?.focused, snap.state.open, session]);

  const open = snap.state.open;
  const view = snap.state.view;

  // Session lifecycle + key ownership follow the overlay's open flag.
  useLayoutEffect(() => {
    const ctx = ctxRef.current;
    if (!ctx) return;
    if (open && !token.current) {
      token.current = session.open(screenRef.current);
    }
    if (open) {
      ctx.setKeyOwner({
        scope: () => overlayFocusableIds(overlayRef.current),
        onBack: () => controller.back(),
        onKey: () => controller.anyKey(),
      });
    } else {
      ctx.setKeyOwner(null);
      if (token.current) {
        const t = token.current;
        token.current = null;
        session.close(t, screenRef.current);
      }
    }
  }, [open, nav, session, controller]);

  // Entry focus per state, in the same commit as the view change.
  useLayoutEffect(() => {
    const ctx = ctxRef.current;
    if (!ctx || !open || view === "idle") return;
    const id = ENTRY_FOCUS[view];
    if (ctx.nav.focus(id)) ctx.focus(id);
  }, [open, view, nav]);

  // Remote openTimerOverlay (PM Option C): only while no other modal owns keys.
  useEffect(() => {
    const ctx = ctxRef.current;
    if (!ctx) return;
    ctx.setTimerOpener(keyEnabled ? () => controller.open() : null);
    return () => ctx.setTimerOpener(null);
  }, [nav, keyEnabled, controller]);

  const actions: TimerActions = {
    choose: (p, ev) => {
      chime.unlock(ev);
      void controller.choosePreset(p);
    },
    pause: () => void controller.pause(),
    resume: () => void controller.resume(),
    requestStop: () => controller.requestStop(),
    requestReplace: () => controller.requestReplace(),
    confirmStop: () => void controller.confirmStop(),
    cancel: () => controller.cancel(),
    acknowledge: () => void controller.acknowledge(),
    requestErase: () => controller.requestErase(),
    confirmErase: () => void controller.confirmErase(),
    back: () => controller.back(),
    togglePresentation: () => void controller.togglePresentation(),
  };

  const label = utilityLabel(snap.state.record, snap.remainingMs);
  return (
    <>
      <div className="nila-timer-utility-slot">
        <Focusable
          id={FALLBACK_FOCUS_ID}
          className="nila-timer-utility"
          navigable={false}
          ariaLabel="Timer"
          onOk={() => controller.open()}
        >
          <span className="nila-timer-utility-icon" aria-hidden="true" />
          {label.kind === "time" && <span className="nila-timer-utility-text">{label.text}</span>}
          {label.kind === "paused" && <span className="nila-timer-utility-text">Paused</span>}
          {label.kind === "done" && <span className="nila-timer-utility-text">0:00</span>}
          <span className="nila-timer-utility-key" aria-hidden="true" />
        </Focusable>
      </div>
      <div ref={overlayRef}>
        <TimerOverlay snap={snap} actions={actions} reducedMotion={reduced} />
      </div>
    </>
  );
}
