/**
 * Per-kid-per-card watch progress (spec v1.1 Y6/D7 resume). Persists the
 * last LEGITIMATELY played point and the Done latch - never a seek target.
 * localStorage, namespaced; no child identifiers beyond the server kid id
 * the app already holds (C3).
 */

const PREFIX = "nila-video-progress:";

export interface StoredVideoProgress {
  /** Max accepted playhead position across sessions (the resume point). */
  maxAcceptedPositionS: number;
  /** Cumulative accepted play time. */
  acceptedS: number;
  /** The Done latch (C7): once earned, stays earned. */
  unlocked: boolean;
}

export function readVideoProgress(kidId: string, cardId: string): StoredVideoProgress | null {
  try {
    const raw = localStorage.getItem(PREFIX + kidId + ":" + cardId);
    if (!raw) return null;
    const p = JSON.parse(raw) as StoredVideoProgress;
    if (typeof p.maxAcceptedPositionS !== "number" || typeof p.acceptedS !== "number") return null;
    return { ...p, unlocked: p.unlocked === true };
  } catch {
    return null;
  }
}

export function writeVideoProgress(
  kidId: string,
  cardId: string,
  progress: StoredVideoProgress,
): void {
  try {
    localStorage.setItem(PREFIX + kidId + ":" + cardId, JSON.stringify(progress));
  } catch {
    // Storage full or denied: progress simply becomes session-local. The
    // latch never pays twice - the mint idempotency key is server-side (C6).
  }
}

export function clearVideoProgress(kidId: string, cardId: string): void {
  try {
    localStorage.removeItem(PREFIX + kidId + ":" + cardId);
  } catch {
    /* ignore */
  }
}
