/**
 * YouTube player-API wrapper (spec v1.1 Y3/Y4). This is the ONLY file in the
 * app allowed to name YouTube: the runtime builds the player from the
 * canonical ID alone, on youtube.com (youtube-nocookie.com is forbidden -
 * ISP-DNS-blocked on the founder's own connection), with minimal params, the
 * origin pinned to the exact app origin, and the iframe focus-inert
 * (tabindex=-1, controls=0, disablekb=1) so remote focus never falls into
 * player chrome. No arbitrary iframe or embed HTML is ever authored.
 */

export interface YTPlayerLike {
  playVideo(): void;
  pauseVideo(): void;
  seekTo(seconds: number, allowSeekAhead: boolean): void;
  getCurrentTime(): number;
  getDuration(): number;
  getPlayerState(): number;
  getVolume(): number;
  setVolume(v: number): void;
  mute(): void;
  unMute(): void;
  isMuted(): boolean;
  loadVideoById(videoId: string): void;
  destroy(): void;
}

interface YTNamespace {
  Player: new (
    el: HTMLElement,
    opts: Record<string, unknown> & {
      videoId: string;
      events: Record<string, (e: { data: number; target: YTPlayerLike }) => void>;
    },
  ) => YTPlayerLike;
  PlayerState: { PLAYING: number; PAUSED: number; ENDED: number; BUFFERING: number };
}

declare global {
  interface Window {
    YT?: YTNamespace;
    onYouTubeIframeAPIReady?: () => void;
  }
}

let apiPromise: Promise<YTNamespace> | null = null;

/** Load the IFrame API exactly once. Rejects after a 10s timeout (Y7). */
export function loadYouTubeApi(): Promise<YTNamespace> {
  if (apiPromise) return apiPromise;
  apiPromise = new Promise((resolve, reject) => {
    if (window.YT) return resolve(window.YT);
    const timeout = window.setTimeout(() => {
      apiPromise = null;
      reject(new Error("player-api-timeout"));
    }, 10_000);
    window.onYouTubeIframeAPIReady = () => {
      window.clearTimeout(timeout);
      resolve(window.YT!);
    };
    const tag = document.createElement("script");
    tag.src = "https://www.youtube.com/iframe_api";
    tag.onerror = () => {
      window.clearTimeout(timeout);
      apiPromise = null;
      reject(new Error("player-api-network"));
    };
    document.head.appendChild(tag);
  });
  return apiPromise;
}

export type YouTubeUnavailable =
  | "video-unavailable" // 100: removed or private
  | "embedding-disabled" // 101/150
  | "invalid-parameter" // 2
  | "html5-error" // 5
  | "network-failure"
  | "player-api-timeout";

/** Y7: player API error codes map onto the branded unavailable family. */
export function mapPlayerError(code: number): YouTubeUnavailable {
  switch (code) {
    case 2:
      return "invalid-parameter";
    case 5:
      return "html5-error";
    case 100:
      return "video-unavailable";
    case 101:
    case 150:
      return "embedding-disabled";
    default:
      return "video-unavailable";
  }
}

export const YT_STATE = { UNSTARTED: -1, ENDED: 0, PLAYING: 1, PAUSED: 2, BUFFERING: 3 } as const;

export interface MountOptions {
  videoId: string;
  /** Exact app origin; the player rejects arbitrary origins (Y4). */
  origin: string;
  onStateChange: (state: number) => void;
  onError: (reason: YouTubeUnavailable) => void;
  onReady: () => void;
  captionsPreferred?: boolean;
}

/**
 * Mount a focus-inert player. Returns the handle, or throws when the API
 * cannot load (caller renders the Y7 branded state).
 */
export async function mountYouTubePlayer(
  host: HTMLElement,
  opts: MountOptions,
): Promise<YTPlayerLike> {
  const YT = await loadYouTubeApi();
  return new YT.Player(host, {
    videoId: opts.videoId,
    playerVars: {
      autoplay: 1, // Y1: zero-press auto-start (founder doctrine)
      controls: 0,
      disablekb: 1,
      rel: 0,
      modestbranding: 1,
      playsinline: 1,
      iv_load_policy: 3,
      fs: 0,
      cc_load_policy: opts.captionsPreferred ? 1 : 0,
      origin: opts.origin,
    },
    events: {
      onReady: () => {
        // Y3: the iframe never takes focus from the remote.
        const iframe = host.querySelector("iframe");
        if (iframe) {
          iframe.setAttribute("tabindex", "-1");
          iframe.setAttribute("aria-hidden", "true");
        }
        opts.onReady();
      },
      onStateChange: (e: { data: number }) => opts.onStateChange(e.data),
      onError: (e: { data: number }) => opts.onError(mapPlayerError(e.data)),
    },
  });
}

/** Real YouTube thumbnail for the kid picker (founder requirement, Sep 23). */
export function videoThumbnailUrl(videoId: string): string {
  return `https://i.ytimg.com/vi/${videoId}/hqdefault.jpg`;
}
