/**
 * Card art resolution. A card renders a painted tile (its corpus tile or the
 * semantic-art match) or nothing. The art-block gate is absolute: an
 * art-pending card renders no art rather than a wrong-kid or generic
 * substitute (the boy's-card-shows-a-girl break and the generic star-catch
 * scene both broke picture trust).
 */

/** The painted tile for a corpus card; may 404 while the art lane fills the set - callers fall back via onError. */
export function cardTile(corpusId: string | null | undefined): string | null {
  return corpusId ? `assets/tiles/${corpusId}.jpg` : null;
}

/** Face-picker fallbacks while kid avatars are unset server-side. */
export const FACE_TILES = ["assets/design/face-ari.png", "assets/design/face-mira.png"];

export const STAR = "assets/design/star.png";

/** The art a card may render, honoring the art-pending gate. */
export function cardArt(card: {
  characterImage?: string | null;
  artCorpusId?: string | null;
  corpusId?: string | null;
  artPending?: boolean;
}): string | null {
  if (card.artPending) return null;
  return card.characterImage ?? cardTile(card.artCorpusId ?? card.corpusId ?? null);
}

/** Public/ asset URL honoring the Vite base (app is served under /nila-app/). */
export const assetUrl = (p: string) => import.meta.env.BASE_URL + p.replace(/^\//, "");

/** Picker kid-stage art fallback chain (E1.12, mock canon): cutout -> face
    crop on the same stage geometry -> warm initial medallion. Never a blank
    stage. */
export type PickerArtStage = "cutout" | "face" | "initial";
export function pickerArtFallbackStage(stage: PickerArtStage, hasFace: boolean): PickerArtStage {
  if (stage === "cutout") return hasFace ? "face" : "initial";
  return "initial";
}
export function pickerInitial(name: string): string {
  const t = name.trim();
  return t.length > 0 ? t.charAt(0).toUpperCase() : "?";
}

/** sizes= for the Welcome hero slot: mirrors .nila-welcome-hero-slot's
 *  clamp(280px, 44vh, 480px) on phones, its 480px cap beyond. */
export const WELCOME_HERO_SIZES = "(max-width: 480px) 44vh, 480px";
/** sizes= for the brand corner mark (.picker-brand clamp(44px, 6.4vh, 70px)). */
export const WELCOME_BRAND_SIZES = "70px";

/** Responsive candidate set for a large character asset (Welcome hero).
 *  Convention: <stem>-<w>.webp for every width, <stem>-<smallest>.png as the
 *  ancient-browser fallback, and the original PNG as the largest PNG
 *  candidate. Payload ruling (PM 2026-09-24): WebP first, current format as
 *  fallback, <=150KB served at phone widths. */
export interface ResponsiveImageSet {
  /** WebP candidates, ascending ("url 400w, url 717w"). */
  webpSrcSet: string;
  /** PNG candidates for browsers without WebP (smallest variants + original). */
  pngSrcSet: string;
  /** Smallest PNG - the img src ancient browsers fetch. */
  fallbackSrc: string;
}

export function responsiveImageSet(
  assetPath: string,
  widths: readonly number[],
): ResponsiveImageSet {
  const sorted = [...widths].sort((a, b) => a - b);
  if (sorted.length === 0) {
    // No responsive variants for this asset: plain single-source render.
    return { webpSrcSet: "", pngSrcSet: "", fallbackSrc: assetUrl(assetPath) };
  }
  const stem = assetPath.replace(/\.png$/, "");
  const webp = sorted.map((w) => `${assetUrl(`${stem}-${w}.webp`)} ${w}w`);
  const png = sorted.slice(0, -1).map((w) => `${assetUrl(`${stem}-${w}.png`)} ${w}w`);
  png.push(`${assetUrl(assetPath)} ${sorted[sorted.length - 1]}w`);
  return {
    webpSrcSet: webp.join(", "),
    pngSrcSet: png.join(", "),
    fallbackSrc: assetUrl(`${stem}-${sorted[0]}.png`),
  };
}
