/** TV focus bridge: the yellow ring, DOM focus and Enter share one source of truth. */
import React, {
  createContext,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { SpatialNav, mapRemoteKey, type RemoteCommand } from "./SpatialNav";
import { focusPreventScroll } from "./focus-options";
import { KeyPressGuard } from "./KeyPressGuard";

/**
 * A modal key owner (timer overlay). While set: arrows move only inside
 * scope() (fresh snapshot per press, fail closed), Back goes to onBack, and
 * onKey may consume any command first (finish capture: no key leaks).
 */
export interface KeyOwner {
  scope: () => Iterable<string>;
  onBack: () => void;
  onKey?: (cmd: RemoteCommand) => boolean;
}

interface FocusContextValue {
  nav: SpatialNav;
  focused: string | null;
  focus: (id: string) => void;
  setKeyOwner: (owner: KeyOwner | null) => void;
  /** Handler for the openTimerOverlay remote command; null = command inert. */
  setTimerOpener: (open: (() => void) | null) => void;
}

/** Same-frame ring sync: the visible class follows nav truth before React re-renders. */
function syncFocusedClass(id: string | null): HTMLElement | null {
  document.querySelectorAll<HTMLElement>(".nila-focused").forEach((el) => {
    if (el.getAttribute("data-focus-id") !== id) el.classList.remove("nila-focused");
  });
  if (!id) return null;
  const el = document.querySelector<HTMLElement>(`[data-focus-id="${CSS.escape(id)}"]`);
  el?.classList.add("nila-focused");
  return el;
}
/** Scroll-invariant position for the completed-card action pair. Their
 * centers can shift after mount without a ResizeObserver size notification. */
function focusRect(el: HTMLElement) {
  const r = el.getBoundingClientRect();
  let x = r.x;
  let y = r.y;
  for (let sc = el.parentElement; sc; sc = sc.parentElement) {
    x += sc.scrollLeft;
    y += sc.scrollTop;
  }
  return { x, y, w: r.width, h: r.height };
}

const FocusContext = createContext<FocusContextValue | null>(null);

export function FocusRoot({ children, onBack }: { children: React.ReactNode; onBack: () => void }) {
  const nav = useMemo(() => new SpatialNav(), []);
  const keyGuard = useMemo(() => new KeyPressGuard(), []);
  const [focused, setFocused] = useState<string | null>(null);
  const keyOwner = useRef<KeyOwner | null>(null);
  const timerOpener = useRef<(() => void) | null>(null);
  const focus = (id: string) => {
    if (!nav.focus(id)) return;
    setFocused(id);
    const el = syncFocusedClass(id);
    if (el) focusPreventScroll(el);
  };
  const setKeyOwner = useMemo(() => (owner: KeyOwner | null) => (keyOwner.current = owner), []);
  const setTimerOpener = useMemo(
    () => (open: (() => void) | null) => (timerOpener.current = open),
    [],
  );

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const cmd = mapRemoteKey(e.key);
      const owner = keyOwner.current;
      if (cmd.type === "ignored") {
        owner?.onKey?.(cmd);
        return;
      }
      e.preventDefault();
      // F7: ok and back act once per physical press. A keydown that changes
      // the screen must not let the same press's repeats or re-dispatched
      // tail activate whatever has focus where it lands (breaks C3).
      if ((cmd.type === "ok" || cmd.type === "back") && !keyGuard.shouldAct(e.key, e.repeat)) {
        return;
      }
      if (owner?.onKey?.(cmd)) return;
      if (cmd.type === "openTimerOverlay") {
        // Respects modal key capture: inert while any key owner is active.
        if (!owner && !e.repeat) timerOpener.current?.();
        return;
      }
      if (cmd.type === "move") {
        // This pair is position-sensitive even when its size is unchanged.
        // Leave other screens' established mount/resize geometry alone.
        document
          .querySelectorAll<HTMLElement>("main.nila-completed [data-focus-id]")
          .forEach((el) => {
            const id = el.getAttribute("data-focus-id");
            if (id) nav.updateRect(id, focusRect(el));
          });
        const id = owner ? nav.move(cmd.direction, owner.scope()) : nav.move(cmd.direction);
        if (id) {
          setFocused(id);
          const el = syncFocusedClass(id);
          if (el) focusPreventScroll(el);
        }
      }
      if (cmd.type === "back") (owner ? owner.onBack : onBack)();
      // Containment: while a key owner is active, OK acts only on an in-scope
      // focus - a stale out-of-scope focus never leaks OK to the page below.
      if (cmd.type === "ok" && nav.focused && owner && ![...owner.scope()].includes(nav.focused))
        return;
      if (cmd.type === "ok" && nav.focused) {
        const selected = document.querySelector<HTMLElement>(
          `[data-focus-id="${CSS.escape(nav.focused)}"]`,
        );
        if (selected) focusPreventScroll(selected);
        selected?.click();
      }
    };
    const release = (e: KeyboardEvent) => keyGuard.release(e.key);
    const unjam = () => keyGuard.reset(); // a keyup lost to a blur must not jam the remote
    window.addEventListener("keydown", handler);
    window.addEventListener("keyup", release);
    window.addEventListener("blur", unjam);
    return () => {
      window.removeEventListener("keydown", handler);
      window.removeEventListener("keyup", release);
      window.removeEventListener("blur", unjam);
    };
  }, [nav, onBack, keyGuard]);

  const value = useMemo(
    () => ({ nav, focused, focus, setKeyOwner, setTimerOpener }),
    [nav, focused, setKeyOwner, setTimerOpener],
  );
  return <FocusContext.Provider value={value}>{children}</FocusContext.Provider>;
}

export function useFocusContext(): FocusContextValue | null {
  return useContext(FocusContext);
}

export function Focusable({
  id,
  onOk,
  className = "",
  autoFocus = false,
  navigable = true,
  ariaLabel,
  children,
}: {
  id: string;
  onOk: () => void;
  className?: string;
  /** Land the remote here when the screen mounts (ui-spec: shelf focuses card one). */
  autoFocus?: boolean;
  /** false = inert utility: pointer/programmatic focus only (timer launcher). */
  navigable?: boolean;
  ariaLabel?: string;
  children: React.ReactNode;
}) {
  const ctx = useContext(FocusContext);
  const ref = useRef<HTMLButtonElement>(null);
  // Layout effect: registration lands before paint, so a same-commit
  // programmatic focus (overlay entry, origin restore) finds the element.
  useLayoutEffect(() => {
    const el = ref.current;
    if (!ctx || !el) return;
    const measure = () => {
      const r = el.getBoundingClientRect();
      /* Register in scroll-invariant coordinates. Viewport rects go stale the
         moment a scroller moves; a card re-measured mid-scroll (lantern's
         focused-width growth fires the ResizeObserver) then registers FRESH
         viewport geometry against every sibling's stale rect, and move()
         picks a stale neighbour that is really behind (measured: D-pad right
         on a scrolled 20-card lantern shelf jumped v8 -> v5 -> v3 and never
         reached the last card). Adding each ancestor's scroll offset keeps
         stale and fresh measurements in the same content space, so ordering
         survives scrolling. Non-scrolling ancestors contribute 0. */
      let x = r.x;
      let y = r.y;
      for (let sc = el.parentElement; sc; sc = sc.parentElement) {
        x += sc.scrollLeft;
        y += sc.scrollTop;
      }
      ctx.nav.register({
        id,
        rect: { x, y, w: r.width, h: r.height },
        ...(navigable ? {} : { navigable: false }),
      });
    };
    measure();
    // Layout keeps moving after mount (sibling faces swap when the server
    // list lands, fluid reflows): a stale rect poisons directional scores
    // and stole the picker's wake focus (walk K2, 2026-09-11).
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    if (ctx.nav.focused === id) requestAnimationFrame(() => ctx.focus(id));
    if (autoFocus) requestAnimationFrame(() => ctx.focus(id));
    return () => {
      ro.disconnect();
      ctx.nav.unregister(id);
      // If the unmounted element held focus, nav already fell back to the
      // first enabled item - sync the visible ring to that fallback.
      // Read the fallback when the frame runs, not now: a same-commit
      // programmatic focus (overlay entry focus) must not be overwritten
      // by a stale fallback captured during unmount.
      if (ctx.nav.focused)
        requestAnimationFrame(() => {
          const fallback = ctx.nav.focused;
          if (fallback) ctx.focus(fallback);
        });
    };
  }, [ctx?.nav, id]);
  const isFocused = ctx?.focused === id;
  useEffect(() => {
    if (!isFocused) return;
    const el = ref.current;
    if (!el) return;
    // Single scroll strategy (ui-spec: carousel scroll & focus restore):
    // center the focused card in its horizontal scroller with a computed,
    // clamped scrollLeft. scrollIntoView("nearest") fought the snap
    // alignment and left the first card half-clipped after scrolling right
    // and back (on-device bug, 2026-09-11). Clamped ends restore flush.
    let scroller = el.parentElement;
    while (scroller) {
      if (/(auto|scroll)/.test(getComputedStyle(scroller).overflowX)) break;
      scroller = scroller.parentElement;
    }
    if (!scroller) {
      el.scrollIntoView({ block: "nearest", inline: "nearest" });
      return;
    }
    // Already fully visible: no gratuitous scroll. First-paint auto-focus on
    // an overflowing row must not center the first item and clip its
    // siblings (DS-1 picker: 3 stages at phone width). Off-screen or
    // partially clipped still center-scrolls - the 2026-09-11 restore fix
    // is untouched (a card scrolled out of view is never "fully visible").
    //
    // DS-1 repair: rect-based math, never offsetLeft - position:relative
    // containment repairs re-root offsetParent and silently break
    // offsetLeft/scrollLeft comparisons. And "fully visible" includes the
    // focus ring: the mock ::before ring box rides 1.2vh OUTSIDE the card's
    // border box, so a flush card still clips its ring at the scroller ends.
    const srect = scroller.getBoundingClientRect();
    const erect = el.getBoundingClientRect();
    // Ring overhang + focus-scale allowance: the effect measures before the
    // 160ms focus transition lands, but the painted card scales ~1.06 about
    // its center - a box that fits unscaled can clip scaled (peek-card trap).
    const ringMargin = Math.ceil(window.innerHeight * 0.012) + 2 + Math.ceil(erect.width * 0.03);
    if (erect.left - ringMargin < srect.left || erect.right + ringMargin > srect.right) {
      const max = Math.max(0, scroller.scrollWidth - scroller.clientWidth);
      const centerDelta = (erect.left + erect.right) / 2 - (srect.left + srect.right) / 2;
      scroller.scrollTo({ left: Math.max(0, Math.min(scroller.scrollLeft + centerDelta, max)) });
    }
    /* fix-1 (PM ruling 15:53): the FOCUSED card must also be fully visible
       VERTICALLY, ring included. The shelf screen owns the page's vertical
       scroll (overflow-y:auto); a focused card can sit past the fold
       (measured on base AND candidate: dB -0.1..-5.9 at 390/412/768/1280/
       1470/2048, fixture ringclip 88addc82). Reveal with a minimal
       nearest-edge scroll, never more than needed - unfocused cards below
       the fold are fine by design. Top allowance includes the 0.06*height
       focus-scale growth about the bottom origin (the transition has not
       landed when this measures); bottom allowance is the ring alone. */
    let vscroller = el.parentElement;
    while (vscroller) {
      if (/(auto|scroll)/.test(getComputedStyle(vscroller).overflowY)) break;
      vscroller = vscroller.parentElement;
    }
    if (vscroller) {
      const vr = vscroller.getBoundingClientRect();
      const ringTop = Math.ceil(window.innerHeight * 0.012) + 2 + Math.ceil(erect.height * 0.06);
      const ringBottom = Math.ceil(window.innerHeight * 0.012) + 2;
      if (erect.top - ringTop < vr.top) {
        vscroller.scrollTo({ top: Math.max(0, vscroller.scrollTop + (erect.top - ringTop - vr.top)) });
      } else if (erect.bottom + ringBottom > vr.bottom) {
        const vmax = Math.max(0, vscroller.scrollHeight - vscroller.clientHeight);
        vscroller.scrollTo({ top: Math.min(vmax, vscroller.scrollTop + (erect.bottom + ringBottom - vr.bottom)) });
      }
    }
  }, [isFocused]);
  return (
    <button
      ref={ref}
      data-focus-id={id}
      className={`${className} nila-focusable ${isFocused ? "nila-focused" : ""}`}
      onFocus={() => ctx?.focus(id)}
      onPointerDown={() => ctx?.focus(id)}
      onClick={onOk}
      tabIndex={isFocused && navigable ? 0 : -1}
      aria-label={ariaLabel}
    >
      {children}
    </button>
  );
}
