/* SHELF P0 gate aid: ?shot=shelf&cards=N (1..20) pins the strip length so the
   natural-path matrix covers 1/2/3/5/10/20-card shelves deterministically.
   Production never sets the param; the base five are the mock's own stack.
   v5 repair: regenerated ids (-vN suffix) must not strand focusCardId on a
   non-existent id - remap it to the pooled index when present, drop it when
   the slice is too short (autoFocus then falls to card one, ui-spec canon). */
function shelfWithCount(n: number | null): ScreenDefinition {
  const base = shelfSeed;
  if (n === null || n === 5) return base;
  const pool = base.cards;
  const cards = Array.from({ length: n }, (_, i) => ({
    ...pool[i % pool.length],
    id: `${pool[i % pool.length].id}-v${i}`,
  }));
  const focusIdx = pool.findIndex((c) => c.id === base.focusCardId);
  const focusCardId =
    focusIdx >= 0 && focusIdx < n ? `${base.focusCardId}-v${focusIdx}` : undefined;
  return { ...base, cards, focusCardId };
}

