/* PM ruling (backlog 189, relayed 2026-09-15): the generic "celebration"
   key STAYS in beats.txt/SHOT_BEATS for now, but it is an ALIAS whose
   canonical evidence cells are the certified cele-* package fixtures.
   Beat/cell counts in reports must never count "celebration" independently
   of the family below. Retirement is a later builder-only shared-index
   cleanup after a consumer census. */
export const SHOT_BEAT_ALIASES: Record<string, readonly string[]> = {
  celebration: ["cele-close", "cele-hero"],
} as const;

/* Theme -> seeded concept for the VD package cells, read from the shot
   URL's theme param (the harness passes one per cell). Deterministic. */
function packageConcept() {
  const theme =
    typeof window !== "undefined" ? new URLSearchParams(window.location.search).get("theme") : null;
  switch (theme) {
    case "lantern":
      return "growing-thing" as const; // C4 - the lantern top-anchored variant
    case "inkverse":
      return "firework-fountain" as const; // C3
    case "chalkboard":
      return "shape-hop" as const; // C5
    default:
      return "confetti-bloom" as const; // C1 (clay + fallback)
  }
}

