export function shotFixture(beat: string, cards: number | null = null): ScreenDefinition | null {
  if (beat in VIDEO_FIXTURES) return VIDEO_FIXTURES[beat]!;
  // SHELF P0 gate aid: ?shot=shelf&cards=N pins the strip length for the
  // 1/2/3/5/10-card natural-path matrix. Every other beat ignores the param.
  if (beat === "shelf" && cards !== null) return shelfWithCount(cards);
  return FIXTURES[beat] ?? null;
}
