/**
 * Celebration draw (celebrations.design.collab.md r4, R3/R8/R9/R11):
 * one concept per completion from a flat pool of five, the kid's last-played
 * concept excluded, the exclusion persisted per kid so the no-repeat rule
 * survives closing the app. The weekly-line JACKPOT is deterministic (R16)
 * and never enters this pool.
 *
 * The weight table is one constant (R8): flat 20 each. Changing it is a spec
 * edit, not a tuning flag.
 */
export const CELEBRATION_POOL = [
  "confetti-bloom",
  "firework-fountain",
  "growing-thing",
  "shape-hop",
  "mascot-big",
] as const;
export type CelebrationConceptId = (typeof CELEBRATION_POOL)[number];

/** Uniform over the pool minus the exclusion; re-normalized flat weights (R9). */
export function drawConcept(
  exclude: string | null,
  rng: () => number = Math.random,
): CelebrationConceptId {
  const eligible = CELEBRATION_POOL.filter((c) => c !== exclude);
  return eligible[Math.floor(rng() * eligible.length)]!;
}

const storageKey = (kidId: string) => `nila:celebration:last:${kidId}`;
const store = () =>
  typeof localStorage !== "undefined"
    ? localStorage
    : (globalThis as { localStorage?: Storage }).localStorage;

export function readLastConcept(kidId: string): string | null {
  try {
    return store()?.getItem(storageKey(kidId)) ?? null;
  } catch {
    return null;
  }
}

export function writeLastConcept(kidId: string, concept: CelebrationConceptId): void {
  try {
    store()?.setItem(storageKey(kidId), concept);
  } catch {
    // private mode / quota: the no-repeat rule degrades to session memory, never breaks the moment
  }
}
