/**
 * Character packs (founder directive 2026-09-15 13:03 IST, verbatim:
 * "have it as a tunable that i can decide later" / "or character will
 * change" / "just like theme" / "zerbra is something i like to start
 * with"). The host character is a swappable pack, architected like the
 * theme system: manifest-driven, swappable without layout changes.
 *
 * Elephant (current Nila art) is the DEFAULT. Zig the Zebra is the first
 * alternate wired in - "first in", not a default swap; switching is a
 * one-line config the founder can flip. Never two characters in one
 * moment (PM, backlog 166).
 *
 * Pose mapping (PM verdict, backlog 166 - binding limits: already-
 * reachable states only; errors, neutral completion, passive coach copy
 * and background work without an existing visible wait state get NO art):
 *   welcome/brand                    -> base
 *   confirmed win                    -> celebrating
 *   explicit user-invoked hint/help  -> pointing
 *   existing visible loading/wait    -> thinking
 *
 * Headroom/crop/scale is a TUNABLE per character per surface. The
 * default on every surface is full headroom (contain) - "tablet-style
 * full headroom", founder tunes later with no code change beyond this
 * config. The wide welcome head-crop fix lands as this tunable's
 * default, not a frozen value (VD's mock-side contain fix, pin
 * 756bff30, is the same semantic - the tunable subsumes it).
 */

export type CharacterPose = "base" | "pointing" | "thinking" | "celebrating";

/** Surfaces the host character can appear on (welcome-hero first - VD
 *  canon v2.0 re-issue scope; brand corner mark rides the same pack). */
export type CharacterSurface = "welcome-hero" | "brand";

export interface SurfaceTunable {
  /** cover = fill the box, crop overflow (OLD welcome bug); contain =
   *  full headroom, letterbox (the default and the wide-crop fix). */
  fit: "cover" | "contain";
  /** CSS object-position; default centered. */
  position?: string;
}

export interface CharacterPack {
  id: string;
  /** Kid/founder-facing name (pack manifest.json "name"). */
  name: string;
  /** Pose -> asset path under assets/. Poses the pack does not carry fall
   *  back to base (PM limit: no inferred art for unreachable states). */
  poses: Partial<Record<CharacterPose, string>>;
  /** Per-surface tunable overrides; absent surface = DEFAULT_TUNABLE. */
  surfaces?: Partial<Record<CharacterSurface, SurfaceTunable>>;
  /** Candidate pixel widths for the responsive base asset (Welcome hero):
   *  variants live at <stem>-<w>.webp plus <stem>-<smallest>.png; the
   *  original PNG doubles as the largest-width PNG candidate. Ascending. */
  baseWidths?: readonly number[];
}

/** The tunable default: full headroom on every surface. The founder
 *  tunes per character per surface later - edit this config, deploy. */
export const DEFAULT_SURFACE_TUNABLE: SurfaceTunable = { fit: "contain", position: "50% 50%" };

export const CHARACTER_PACKS: readonly CharacterPack[] = [
  {
    id: "nila-elephant",
    name: "Nila",
    poses: {
      /* Current production art stays the elephant pack's base until the
         founder says otherwise (Q2 settled: ella-the-elephant is a
         SEPARATE character, no identity swap without sign-off). */
      base: "assets/characters/elephant-cutout.png",
      celebrating: "assets/characters/elephant-cheer.png",
    },
    baseWidths: [400, 717],
  },
  {
    id: "zig-the-zebra",
    name: "Zig the Zebra",
    poses: {
      base: "assets/characters/packs/zig-the-zebra/base.png",
      pointing: "assets/characters/packs/zig-the-zebra/pointing.png",
      thinking: "assets/characters/packs/zig-the-zebra/thinking.png",
      celebrating: "assets/characters/packs/zig-the-zebra/celebrating.png",
    },
    baseWidths: [400, 1024],
  },
];

export type CharacterId = (typeof CHARACTER_PACKS)[number]["id"];

export const DEFAULT_CHARACTER: CharacterId = "nila-elephant";

const STORAGE_KEY = "nila-character-v1";
const IDS: string[] = CHARACTER_PACKS.map((p) => p.id);

export function readCharacter(): CharacterId {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    return IDS.includes(raw ?? "") ? (raw as CharacterId) : DEFAULT_CHARACTER;
  } catch {
    return DEFAULT_CHARACTER;
  }
}

export function writeCharacter(id: CharacterId): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, id);
  } catch {
    /* private mode: session-local only */
  }
}

/* The active character for this session. Set at boot (App.tsx), overridden
   by the shot harness's ?character= param (shot mode only, exactly like
   ?theme=). Components read it synchronously via currentCharacter(). */
let current: CharacterId = DEFAULT_CHARACTER;

export function applyCharacter(id: CharacterId): void {
  current = IDS.includes(id) ? id : DEFAULT_CHARACTER;
}

export function currentCharacter(): CharacterId {
  return current;
}

export function characterPack(id: CharacterId): CharacterPack {
  return CHARACTER_PACKS.find((p) => p.id === id) ?? CHARACTER_PACKS[0];
}

/** Resolve a pose asset for a pack; missing pose falls back to base. */
export function characterAsset(id: CharacterId, pose: CharacterPose): string {
  const pack = characterPack(id);
  return pack.poses[pose] ?? pack.poses.base!;
}

/** Candidate widths for a pack's responsive base asset; absent = not responsive. */
export function characterBaseWidths(id: CharacterId): readonly number[] | null {
  return characterPack(id).baseWidths ?? null;
}

/** Resolve a surface's tunable for a pack; absent = full-headroom default. */
export function surfaceTunable(id: CharacterId, surface: CharacterSurface): SurfaceTunable {
  return characterPack(id).surfaces?.[surface] ?? DEFAULT_SURFACE_TUNABLE;
}
