import { familyKeyHeaders } from "./family-key";
import {
  drainTelemetryEvents,
  queueTelemetryEvent,
  removeTelemetryEvent,
  type QueuedTelemetryEvent,
} from "../state/offline";

export type PilotEventKind =
  // Beta event set (privacy FINAL 2026-09-15): child-flow engagement kinds
  // are not emitted at all - the server refuses them and the constraint
  // rejects them. Retained: transactions + payload-bare pair operability +
  // service-perf screen-metrics + parent surface events.
  | "completion"
  | "undo"
  | "celebration_shown"
  | "screen-metrics"
  | "pair-required"
  | "pair-saved"
  | "pair-refused"
  | "parent-onboarding"
  | "parent-intent"
  | "parent-hold"
  | "parent-bind"
  | "parent-error"
  | "ladder-graduate"
  | "ladder-locked"
  | "bot-message"
  | "bot-rejected"
  | "reward-add"
  | "star-grant";
// The backend's absolute home. The env override stays for dev proxies, but
// the default must be the real host: a build that forgets the env var
// otherwise falls back to a relative "/api", which on the github.io Pages
// host resolves to sriaitoolkit.github.io/api (404/405 on every call) and
// reads as the muddled screen with a healthy backend (regression shipped
// 2026-09-13 in the store-browse deploy; founder's TV, diag overlay showed
// app calls 404ing while direct probes returned 200).
const API_BASE =
  (import.meta.env?.VITE_NILA_API_BASE as string | undefined) ??
  "https://exrolfmurvaecgkukzrk.supabase.co/functions/v1";

type TelemetryPayload = Omit<QueuedTelemetryEvent, "id" | "queuedAt">;

const post = (payload: TelemetryPayload) =>
  fetch(`${API_BASE}/telemetry`, {
    method: "POST",
    headers: { "content-type": "application/json", ...familyKeyHeaders(payload.kidId) },
    body: JSON.stringify(payload),
    keepalive: true,
  });

// Telemetry is fire-and-forget by design - but never lost by design. A
// failed or offline send lands in the IndexedDB outbox; the next
// successful send drains the queue oldest-first (2026-09-12 loop: offline
// opens used to vanish, breaking the funnel's open attribution).
// Shot mode (?shot=...&theme=...) is the port-gate harness: its boots and
// taps are pixels-for-diff, never product telemetry (2026-09-14 ruling: the
// boot-storm proved harness noise pollutes prod metrics - kill the class).
const inShotMode = () =>
  typeof location !== "undefined" && new URLSearchParams(location.search).has("shot");

export function telemetry(
  kind: PilotEventKind,
  screen: string,
  data: {
    kidId?: string;
    cardId?: string;
    detail?: Record<string, string | number | boolean>;
  } = {},
): void {
  if (inShotMode()) return;
  const payload: TelemetryPayload = { kind, screen, ...data };
  void deliver(payload);
}

async function deliver(payload: TelemetryPayload): Promise<void> {
  try {
    if (typeof navigator !== "undefined" && navigator.onLine === false) throw new Error("offline");
    const res = await post(payload);
    // A 400 is a permanent refusal (a kind the server no longer collects):
    // drop the event - queueing it would poison the outbox forever.
    if (!res.ok && res.status !== 400) throw new Error(`telemetry ${res.status}`);
    void flushQueued();
  } catch {
    try {
      await queueTelemetryEvent({ ...payload, queuedAt: Date.now() });
    } catch {
      // No IndexedDB (private mode, old WebView): drop the event, never the app.
    }
  }
}

let flushing = false;
async function flushQueued(): Promise<void> {
  if (flushing) return;
  flushing = true;
  try {
    const queued = await drainTelemetryEvents();
    for (const event of queued) {
      if (event.id == null) continue;
      try {
        const { kind, screen, kidId, cardId, detail } = event;
        const res = await post({ kind, screen, kidId, cardId, detail });
        if (!res.ok && res.status !== 400) break; // server unhappy: keep the rest queued
        // 400 = permanently refused (e.g. a kind retired while queued): drop it.
        await removeTelemetryEvent(event.id);
      } catch {
        break; // still offline: keep the rest queued
      }
    }
  } catch {
    // outbox unreadable: nothing to flush
  } finally {
    flushing = false;
  }
}
