/** Timer overlay views (spec v3-r "States"). Pure render from a snapshot. */
import { Focusable } from "../../focus/FocusRoot";
import {
  TIMER_PRESETS_MS,
  formatMSS,
  isFinalQuarter,
  racerProgress,
  type TimerView,
} from "../../../../../packages/domain/src/timer";
import { TIMER_COPY, type TimerSnapshot } from "./timer-controller";

export interface TimerActions {
  choose: (presetMs: number, ev: { isTrusted: boolean }) => void;
  pause: () => void;
  resume: () => void;
  requestStop: () => void;
  requestReplace: () => void;
  confirmStop: () => void;
  cancel: () => void;
  acknowledge: () => void;
  requestErase: () => void;
  confirmErase: () => void;
  back: () => void;
  togglePresentation: () => void;
}

/** Entry focus per state (plan s3.5: per-state entryFocus map). */
export const ENTRY_FOCUS: Record<Exclude<TimerView, "idle">, string> = {
  pick: "timer-pick-180000",
  running: "timer-pause",
  "final-quarter": "timer-pause",
  paused: "timer-resume",
  "stop-confirm": "timer-stop-keep",
  "replace-confirm": "timer-pick-180000",
  finished: "timer-done",
  recovery: "timer-recovery-back",
  "erase-confirm": "timer-erase-keep",
  "storage-unavailable": "timer-unavailable-back",
};

const minutes = (ms: number) => `${ms / 60_000} min`;

function Racer({ progress }: { progress: number }) {
  return (
    <div className="nila-timer-track" aria-hidden="true">
      <div
        className="nila-timer-racer"
        style={{ transform: `translateX(${(progress * 100).toFixed(2)}%)` }}
      >
        <span className="nila-timer-racer-art" />
      </div>
      <span className="nila-timer-flag" />
    </div>
  );
}

export function TimerOverlay({
  snap,
  actions,
  reducedMotion,
}: {
  snap: TimerSnapshot;
  actions: TimerActions;
  reducedMotion: boolean;
}) {
  const { state, remainingMs } = snap;
  const view = state.view;
  const rec = state.record;
  if (!state.open || view === "idle") return null;
  const preset = rec?.presetMs ?? 180_000;
  const final = rec?.status === "running" && isFinalQuarter(remainingMs, preset);
  const presentation = rec?.presentation ?? "racer";
  const picks = (
    <div className="nila-timer-actions">
      {TIMER_PRESETS_MS.map((p, i) => (
        <Focusable
          key={p}
          id={`timer-pick-${p}`}
          className={`nila-action nila-timer-pick${i === 0 ? " nila-primary" : ""}`}
          onOk={() => actions.choose(p, { isTrusted: true })}
        >
          {minutes(p)}
        </Focusable>
      ))}
    </div>
  );
  const clock = (
    <p className="nila-timer-mss" aria-label={`${formatMSS(remainingMs)} left`}>
      {formatMSS(remainingMs)}
    </p>
  );
  let body: React.ReactNode;
  switch (view) {
    case "pick":
      body = (
        <>
          <h1>How long?</h1>
          {picks}
        </>
      );
      break;
    case "running":
    case "final-quarter":
    case "paused":
      body = (
        <>
          {final && <p className="nila-timer-almost">{TIMER_COPY.almost}</p>}
          {view === "paused" && <p className="nila-timer-paused">Paused</p>}
          {presentation === "racer" ? (
            <>
              <Racer progress={racerProgress(remainingMs, preset, reducedMotion)} />
              {clock}
            </>
          ) : (
            <>
              {clock}
              <Racer progress={racerProgress(remainingMs, preset, reducedMotion)} />
            </>
          )}
          <div className="nila-timer-actions">
            {view === "paused" ? (
              <Focusable
                id="timer-resume"
                className="nila-action nila-primary"
                onOk={actions.resume}
              >
                Resume
              </Focusable>
            ) : (
              <Focusable id="timer-pause" className="nila-action nila-primary" onOk={actions.pause}>
                Pause
              </Focusable>
            )}
            <Focusable id="timer-new" className="nila-action" onOk={actions.requestReplace}>
              New timer
            </Focusable>
            <Focusable id="timer-stop" className="nila-action" onOk={actions.requestStop}>
              Stop
            </Focusable>
            <Focusable
              id="timer-view-toggle"
              className="nila-action"
              onOk={actions.togglePresentation}
            >
              {presentation === "racer" ? "Show numbers" : "Show racer"}
            </Focusable>
          </div>
        </>
      );
      break;
    case "stop-confirm":
      body = (
        <>
          <h1>{TIMER_COPY.stopTitle}</h1>
          <div className="nila-timer-actions">
            <Focusable
              id="timer-stop-keep"
              className="nila-action nila-primary"
              onOk={actions.cancel}
            >
              Keep going
            </Focusable>
            <Focusable id="timer-stop-confirm" className="nila-action" onOk={actions.confirmStop}>
              Stop timer
            </Focusable>
          </div>
        </>
      );
      break;
    case "replace-confirm":
      body = (
        <>
          <h1>{TIMER_COPY.replaceTitle}</h1>
          {picks}
          <div className="nila-timer-actions">
            <Focusable id="timer-replace-keep" className="nila-action" onOk={actions.cancel}>
              Keep this one
            </Focusable>
          </div>
        </>
      );
      break;
    case "finished":
      body = (
        <>
          <div className="nila-timer-arrival" aria-hidden="true">
            <span className="nila-timer-racer-art" />
          </div>
          <h1>{TIMER_COPY.finished}</h1>
          <p className="nila-timer-mss">0:00</p>
          <div className="nila-timer-actions">
            <Focusable
              id="timer-done"
              className="nila-action nila-primary"
              onOk={actions.acknowledge}
            >
              Done
            </Focusable>
          </div>
        </>
      );
      break;
    case "recovery":
      body = (
        <>
          <h1>{TIMER_COPY.corruptTitle}</h1>
          <p>{TIMER_COPY.corruptBody}</p>
          <div className="nila-timer-actions">
            <Focusable
              id="timer-recovery-back"
              className="nila-action nila-primary"
              onOk={actions.back}
            >
              Back
            </Focusable>
            <Focusable
              id="timer-recovery-fresh"
              className="nila-action"
              onOk={actions.requestErase}
            >
              Start fresh
            </Focusable>
          </div>
        </>
      );
      break;
    case "erase-confirm":
      body = (
        <>
          <h1>{TIMER_COPY.eraseTitle}</h1>
          <div className="nila-timer-actions">
            <Focusable
              id="timer-erase-keep"
              className="nila-action nila-primary"
              onOk={actions.cancel}
            >
              {TIMER_COPY.keep}
            </Focusable>
            <Focusable
              id="timer-erase-confirm"
              className="nila-action nila-destructive"
              onOk={actions.confirmErase}
            >
              {TIMER_COPY.erase}
            </Focusable>
          </div>
        </>
      );
      break;
    case "storage-unavailable":
      body = (
        <>
          <p>{TIMER_COPY.startBlocked}</p>
          <div className="nila-timer-actions">
            <Focusable
              id="timer-unavailable-back"
              className="nila-action nila-primary"
              onOk={actions.back}
            >
              OK
            </Focusable>
          </div>
        </>
      );
      break;
  }
  return (
    <div className="nila-timer-scrim" role="dialog" aria-modal="true" aria-label="Timer">
      <section
        className={`nila-timer-panel${final ? " nila-timer-final" : ""}${reducedMotion ? " nila-timer-reduced" : ""}`}
        data-timer-state={view}
        data-timer-presentation={presentation}
      >
        {body}
      </section>
    </div>
  );
}
