/**
 * Tenancy closure (Option 1, founder ruling 2026-09-14): every family-data
 * call presents the household's key as x-nila-family-key. The real family
 * key is typed once at pairing and stored on the device; it NEVER ships in
 * the bundle. The demo key below ships openly by PM ruling (2026-09-14):
 * demo stays world-open - synthetic data only, and the server verifies the
 * key against the resolved family, so this key unlocks nothing but demo.
 */
export const DEMO_FAMILY_ID = "00000000-0000-4000-8000-000000000003";
export const DEMO_FAMILY_KEY = "nila-3uvb-86ev";
/** Demo Kid + the critic profiles (App.tsx) - all live in the demo family. */
const DEMO_KID_IDS = new Set([
  "00000000-0000-4000-8000-000000000002",
  "00000000-0000-4000-8000-000000000013",
  "00000000-0000-4000-8000-000000000014",
]);

const STORE_KEY = "nila.familyKey";
const STORE_FAMILY_ID = "nila.familyId";

export function storedFamilyKey(): string | null {
  try {
    const k = localStorage.getItem(STORE_KEY);
    return k && k.trim() ? k.trim() : null;
  } catch {
    return null; // old WebView / private mode: unpaired stays unpaired
  }
}

export function saveFamilyKey(key: string): void {
  try {
    localStorage.setItem(STORE_KEY, key.trim().toLowerCase());
  } catch {
    // no storage: the pairing screen will ask again next boot
  }
}

export function clearFamilyKey(): void {
  try {
    localStorage.removeItem(STORE_KEY);
    localStorage.removeItem(STORE_FAMILY_ID);
  } catch {
    // nothing to clear
  }
}

/** The household id captured at pairing (runtime pairing, 2026-09-14): the
 * picker's family source when the bundle carries no build-time id - an APK
 * WebViews the public Pages build, so per-family builds never existed. */
export function storedFamilyId(): string | null {
  try {
    const f = localStorage.getItem(STORE_FAMILY_ID);
    return f && f.trim() ? f.trim() : null;
  } catch {
    return null;
  }
}

export function saveFamilyId(familyId: string): void {
  try {
    localStorage.setItem(STORE_FAMILY_ID, familyId.trim());
  } catch {
    // no storage: pairing will ask again next boot
  }
}

/** Which key to present for a kid-scoped call: demo kids use the shipped
 * demo key, every real kid uses the paired household key. */
export function keyForKid(kidId?: string): string | null {
  if (kidId && DEMO_KID_IDS.has(kidId)) return DEMO_FAMILY_KEY;
  return storedFamilyKey();
}

/** Headers for a family-data call; empty when no key is held (the rollout
 * window still serves, post-enforcement the server answers 401). */
export function familyKeyHeaders(kidId?: string): Record<string, string> {
  const key = keyForKid(kidId);
  return key ? { "x-nila-family-key": key } : {};
}
