/**
 * Legitimately-played progress accumulator (video spec v1.1 D7, Y5, C7, O3).
 *
 * The 90% rule is the pay gate: Done unlocks only at 90% of the admission-
 * validated duration played, or at the end of the video, whichever first.
 * Progress accumulates ONLY from accepted play-time deltas while the player
 * reports PLAYING, sampled at <=1s wall cadence. A delta is accepted only when
 * it is positive and within normal-rate bounds for the elapsed wall time
 * (current playback rate x elapsed, plus jitter tolerance). Seek-to-end jumps,
 * rate inflation, duplicate player events, API reconnects, and replay after
 * completion mint nothing. The unlock is a LATCH: once legitimately earned it
 * stays earned. Resume restores the last legitimately played point, never a
 * seek target.
 *
 * This module is the anti-inheritance guard for the live quiz-integrity defect
 * (stars paid with no answer): there is no code path here that pays or unlocks
 * on open, on partial play, or on seek.
 */

export const WATCH_THRESHOLD = 0.9; // O3: 90% cumulative legitimately played

/** Jitter tolerance on the accepted-delta upper bound (Y5). */
const RATE_JITTER = 0.25;

export interface ProgressSample {
  /** Player-reported playhead, seconds. */
  positionS: number;
  /** Wall clock at sample time, milliseconds (monotonic source). */
  wallMs: number;
  /** Player state: only PLAYING samples can accumulate. */
  playing: boolean;
  /** Current playback rate (1 = normal). */
  rate?: number;
  /** Admission-validated duration, seconds. May shrink mid-play (Y5). */
  durationS?: number;
}

export interface ProgressState {
  /** Cumulative accepted play time, seconds. */
  acceptedS: number;
  /** Max accepted playhead position - the only legal resume point (Y6). */
  maxAcceptedPositionS: number;
  /** Smallest duration seen (Y5: duration changes keep the smaller). */
  durationS: number;
  /** The Done latch (C7). Sticky once true. */
  unlocked: boolean;
  /** Last accepted sample, for delta math. */
  lastPositionS: number | null;
  lastWallMs: number | null;
}

export function initProgress(durationS: number): ProgressState {
  return {
    acceptedS: 0,
    maxAcceptedPositionS: 0,
    durationS,
    unlocked: false,
    lastPositionS: null,
    lastWallMs: null,
  };
}

export interface SampleOutcome {
  state: ProgressState;
  accepted: boolean;
  /** Why a sample was rejected; undefined when accepted. */
  rejected?: "not-playing" | "non-positive-delta" | "seek-jump" | "rate-inflation";
}

/**
 * Feed one sample. Pure and idempotent: feeding the same sample twice accepts
 * it once (the second delta is zero or non-positive and is refused).
 */
export function feedSample(prev: ProgressState, sample: ProgressSample): SampleOutcome {
  // Duration changes mid-play keep the smaller duration (Y5).
  const durationS =
    sample.durationS !== undefined ? Math.min(prev.durationS, sample.durationS) : prev.durationS;

  const state: ProgressState = { ...prev, durationS };

  if (!sample.playing) {
    // Pause/seek/buffer samples reset the delta baseline but never accumulate.
    state.lastPositionS = sample.positionS;
    state.lastWallMs = sample.wallMs;
    return { state, accepted: false, rejected: "not-playing" };
  }

  if (prev.lastPositionS === null || prev.lastWallMs === null) {
    // First playing sample establishes the baseline; it accumulates nothing.
    state.lastPositionS = sample.positionS;
    state.lastWallMs = sample.wallMs;
    return { ...finalize(state), accepted: true };
  }

  const posDelta = sample.positionS - prev.lastPositionS;
  const wallDeltaS = (sample.wallMs - prev.lastWallMs) / 1000;

  state.lastPositionS = sample.positionS;
  state.lastWallMs = sample.wallMs;

  if (posDelta <= 0) {
    // Replays, duplicate events, reconnects re-reporting the same position.
    return { state, accepted: false, rejected: "non-positive-delta" };
  }
  if (wallDeltaS <= 0) {
    return { state, accepted: false, rejected: "non-positive-delta" };
  }

  // Seek-to-end jump: the playhead moved far past what the wall time allows
  // at the current rate. Rejected as progress (Y5); baseline still advances
  // so post-seek PLAYING resumes cleanly from the seek target - but resume
  // never restores it (maxAcceptedPositionS is untouched).
  const rate = sample.rate && sample.rate > 0 ? Math.min(sample.rate, 3) : 1;
  const maxAcceptable = wallDeltaS * rate * (1 + RATE_JITTER);
  if (posDelta > maxAcceptable) {
    const kind = posDelta > wallDeltaS * 4 ? "seek-jump" : "rate-inflation";
    return { state, accepted: false, rejected: kind };
  }

  // Accepted delta (Y5): the playhead advance, capped at what the wall time
  // allows at the current rate - a stalled sample pair can never mint more
  // than real time, and rate inflation past the cap earns nothing.
  const acceptedDelta = Math.min(posDelta, wallDeltaS * rate);
  state.acceptedS = prev.acceptedS + acceptedDelta;
  state.maxAcceptedPositionS = Math.max(prev.maxAcceptedPositionS, sample.positionS);

  return { ...finalize(state), accepted: true };
}

function finalize(state: ProgressState): SampleOutcome {
  // C7: unlock at 90% of duration played or the end, whichever first. Latch.
  if (!state.unlocked && state.durationS > 0) {
    const reachedThreshold = state.acceptedS >= state.durationS * WATCH_THRESHOLD;
    const reachedEnd =
      state.maxAcceptedPositionS >= state.durationS - 0.5 &&
      state.acceptedS >= state.durationS * WATCH_THRESHOLD;
    if (reachedThreshold || reachedEnd) {
      return { state: { ...state, unlocked: true }, accepted: true };
    }
  }
  return { state, accepted: true };
}

/** Y6: the only legal resume point. Never a seek target. */
export function resumePosition(state: ProgressState): number {
  return Math.min(state.maxAcceptedPositionS, state.durationS);
}
