/**
 * Video gate shot states (spec v1.1 D5/Y2/Y7): deterministic compositions for
 * the cold-pixel matrix - picker / playing / completed / autoplay-blocked /
 * error / offline. Mounted ONLY from shot fixtures (?shot=video-*); the
 * production player never imports this file. Static markup mirrors the live
 * player's own classes so the gate diffs the real composition, and nothing
 * here touches the network (thumbnails render the branded fallback tiles).
 */
import { Focusable } from "../focus/FocusRoot";
import type { CardDefinition } from "../state/screens";
import type { ActivityMedia } from "../../../../packages/domain/src/video/media.ts";

const NOOP = () => {};

function Stage({ children }: { children: React.ReactNode }) {
  return <div className="nila-video-stage">{children}</div>;
}

export function VideoShot({
  state,
  card,
}: {
  state: "picker" | "playing" | "completed" | "autoplay-blocked" | "error" | "offline";
  card: CardDefinition & { media: ActivityMedia };
}) {
  if (state === "picker") {
    return (
      <main className="nila-screen nila-video-screen">
        <h1 className="nila-title">{card.title}</h1>
        <div className="nila-video-picker">
          <h2 className="nila-video-picker-title">Pick a video</h2>
          <div className="nila-video-picker-row">
            {card.media.items.map((_, i) => (
              <Focusable
                key={i}
                id={`video-pick-${i}`}
                className="nila-video-pick"
                autoFocus={i === 0}
                onOk={NOOP}
              >
                <div className="nila-video-thumb nila-video-thumb-fallback">Video {i + 1}</div>
              </Focusable>
            ))}
          </div>
          <Focusable id="video-picker-exit" className="nila-action nila-secondary" onOk={NOOP}>
            Back
          </Focusable>
        </div>
      </main>
    );
  }

  if (state === "error" || state === "offline") {
    return (
      <main className="nila-screen nila-video-screen">
        <h1 className="nila-title">{card.title}</h1>
        <Stage>
          <div className="nila-video-bubble" role={state === "error" ? "alert" : "status"}>
            {state === "error"
              ? "This video isn't working right now. Try again later."
              : "No internet right now. This video can play when you're back online."}
          </div>
          <Focusable id="video-exit" className="nila-action nila-secondary" autoFocus onOk={NOOP}>
            Back
          </Focusable>
        </Stage>
      </main>
    );
  }

  if (state === "autoplay-blocked") {
    return (
      <main className="nila-screen nila-video-screen">
        <h1 className="nila-title">{card.title}</h1>
        <Stage>
          {/* Mirrors the live player's in-flow host: the overlay covers the
             16:9 video area (without it a height-auto stage collapses). */}
          <div className="nila-video-host" />
          <div className="nila-video-overlay nila-video-poster">
            <Focusable id="video-play" className="nila-action nila-primary" autoFocus onOk={NOOP}>
              Play
            </Focusable>
          </div>
        </Stage>
      </main>
    );
  }

  // playing / completed: the control surface. completed = the 90% latch has
  // fired, so Done exists; playing shows the partial bar and NO Done (the
  // pay gate made visible).
  const completed = state === "completed";
  return (
    <main className="nila-screen nila-video-screen">
      <h1 className="nila-title">{card.title}</h1>
      <Stage>
        <div className="nila-video-host" />
        <div className="nila-video-controls" role="group" aria-label="Video controls">
          <Focusable id="video-toggle" className="nila-video-ctl" autoFocus onOk={NOOP}>
            Pause
          </Focusable>
          <Focusable id="video-back-10" className="nila-video-ctl" onOk={NOOP}>
            -10s
          </Focusable>
          <Focusable id="video-fwd-10" className="nila-video-ctl" onOk={NOOP}>
            +10s
          </Focusable>
          <Focusable id="video-mute" className="nila-video-ctl" onOk={NOOP}>
            Mute
          </Focusable>
          <div
            className="nila-video-progressbar"
            role="progressbar"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={completed ? 92 : 45}
            aria-label="Watched"
          >
            <div className="nila-video-progressfill" style={{ width: completed ? "92%" : "45%" }} />
          </div>
          <span className="nila-video-clock">{completed ? "1:27 / 1:35" : "0:43 / 1:35"}</span>
          {completed ? (
            <Focusable id="video-done" className="nila-action nila-primary" onOk={NOOP}>
              Done
            </Focusable>
          ) : null}
          <Focusable id="video-exit" className="nila-action nila-secondary" onOk={NOOP}>
            Back
          </Focusable>
        </div>
      </Stage>
    </main>
  );
}
